"""Append the corruption probe's raw output to .gitignore, preserving the file's CRLF endings.

The probe writes one JSON line per user per process (~50 lines/run) into
scratchpad/quant_plan/corruption/probe_out/<tag>/. That is evidence, not source: it is regenerated by
the chain and would otherwise land in the repository as thousands of lines of counters.
"""
from pathlib import Path

P = Path(__file__).resolve().parents[3] / ".gitignore"
BLOCK = (
    "\n"
    "# The corruption check's raw per-user probe output (counters, regenerated by the chain);\n"
    "# the verdicts that matter are scratchpad/quant_plan/corruption/corruption_corrupt_<tag>.json.\n"
    "scratchpad/quant_plan/corruption/probe_out/\n"
)
with P.open(encoding="utf-8", newline="") as fh:
    text = fh.read()
if "corruption/probe_out" in text:
    raise SystemExit("already present")
with P.open("w", encoding="utf-8", newline="") as fh:
    fh.write(text + BLOCK.replace("\n", "\r\n") if "\r\n" in text else text + BLOCK)
print(f"appended to {P} (crlf={'\\r\\n' in text})")
